import{_ as e,o as a,c as r,a4 as o}from"./chunks/framework.vNSRaLQv.js";const p=JSON.parse('{"title":"SSD 写入优化探索记录","description":"","frontmatter":{"title":"SSD 写入优化探索记录","date":"2026-07-08T00:00:00.000Z"},"headers":[],"relativePath":"posts/SSD写入优化探索记录.md","filePath":"posts/SSD写入优化探索记录.md"}'),i={name:"posts/SSD写入优化探索记录.md"};function s(d,t,l,n,h,c){return a(),r("div",null,[...t[0]||(t[0]=[o(`<h1 id="ssd-写入优化探索记录" tabindex="-1">SSD 写入优化探索记录 <a class="header-anchor" href="#ssd-写入优化探索记录" aria-label="Permalink to &quot;SSD 写入优化探索记录&quot;">​</a></h1><blockquote><p>日期：2026-07-08 系统：Windows 11 / 笔记本（核显 + 外接 AMD 显卡）</p></blockquote><hr><h2 id="起因" tabindex="-1">起因 <a class="header-anchor" href="#起因" aria-label="Permalink to &quot;起因&quot;">​</a></h2><p>使用 Codex 6 个月后发现 SSD 写入量异常，半年写入量相当于之前 3.5 年的总写入量，怀疑软件有严重的日志/缓存写入 Bug。</p><hr><h2 id="使用工具" tabindex="-1">使用工具 <a class="header-anchor" href="#使用工具" aria-label="Permalink to &quot;使用工具&quot;">​</a></h2><h3 id="disksleuth-文件事件监控" tabindex="-1">DiskSleuth（文件事件监控） <a class="header-anchor" href="#disksleuth-文件事件监控" aria-label="Permalink to &quot;DiskSleuth（文件事件监控）&quot;">​</a></h3><ul><li>下载：<a href="https://github.com/Swatto86/DiskSleuth/releases" target="_blank" rel="noreferrer">https://github.com/Swatto86/DiskSleuth/releases</a></li><li>Rust 写的单文件绿色版，4.7 MB</li><li>功能：实时监控文件系统变更事件（读/写/打开/关闭）</li><li>原理：<code>ReadDirectoryChangesW</code> API 钩子</li><li><strong>局限</strong>：只能看写入次数，不能看写入字节量</li><li><strong>盲区</strong>：SQLite WAL 模式的长连接写入、mmap 内存映射文件不会触发事件</li></ul><h3 id="process-explorer-进程-io-监控" tabindex="-1">Process Explorer（进程 IO 监控） <a class="header-anchor" href="#process-explorer-进程-io-监控" aria-label="Permalink to &quot;Process Explorer（进程 IO 监控）&quot;">​</a></h3><ul><li>下载：<a href="https://live.sysinternals.com/procexp64.exe" target="_blank" rel="noreferrer">https://live.sysinternals.com/procexp64.exe</a></li><li>功能：按进程显示累计写入字节数（<code>Write Bytes</code> 列）</li><li>用法：右键列头 → Select Columns → Process I/O → 勾 Write Bytes</li><li><strong>优势</strong>：补全 DiskSleuth 的盲区，看真实写入量</li><li><strong>局限</strong>：只能看进程级别，不能看具体文件</li></ul><h3 id="crystaldiskinfo-ssd-健康度" tabindex="-1">CrystalDiskInfo（SSD 健康度） <a class="header-anchor" href="#crystaldiskinfo-ssd-健康度" aria-label="Permalink to &quot;CrystalDiskInfo（SSD 健康度）&quot;">​</a></h3><ul><li>下载：<a href="https://crystalmark.info/en/software/crystaldiskinfo/" target="_blank" rel="noreferrer">https://crystalmark.info/en/software/crystaldiskinfo/</a></li><li>功能：读取 S.M.A.R.T. 数据，查看 SSD 剩余寿命和总写入量</li></ul><hr><h2 id="关键概念" tabindex="-1">关键概念 <a class="header-anchor" href="#关键概念" aria-label="Permalink to &quot;关键概念&quot;">​</a></h2><h3 id="write-amplification-写入放大-waf" tabindex="-1">Write Amplification（写入放大 / WAF） <a class="header-anchor" href="#write-amplification-写入放大-waf" aria-label="Permalink to &quot;Write Amplification（写入放大 / WAF）&quot;">​</a></h3><p>SSD 最小擦除单位是块（256KB-4MB），写几个字节也要读整块→改→擦除→重写。小文件随机写入的 WAF 可达 10-100x。</p><h3 id="micro-write-微写入" tabindex="-1">Micro-write（微写入） <a class="header-anchor" href="#micro-write-微写入" aria-label="Permalink to &quot;Micro-write（微写入）&quot;">​</a></h3><p>每次写几个字节的高频写入模式。浏览器缓存、SQLite WAL、配置文件都属于此类。对 SSD 伤害比看上去大。</p><h3 id="wal-write-ahead-log" tabindex="-1">WAL（Write-Ahead Log） <a class="header-anchor" href="#wal-write-ahead-log" aria-label="Permalink to &quot;WAL（Write-Ahead Log）&quot;">​</a></h3><p>SQLite 的事务日志模式。先追加到 WAL 文件，checkpoint 时合并回主库。Codex 的 <code>logs_2.sqlite-wal</code> 就是典型。</p><hr><h2 id="排查过程" tabindex="-1">排查过程 <a class="header-anchor" href="#排查过程" aria-label="Permalink to &quot;排查过程&quot;">​</a></h2><h3 id="disksleuth-抓到的写入次数排行" tabindex="-1">DiskSleuth 抓到的写入次数排行 <a class="header-anchor" href="#disksleuth-抓到的写入次数排行" aria-label="Permalink to &quot;DiskSleuth 抓到的写入次数排行&quot;">​</a></h3><table tabindex="0"><thead><tr><th>#</th><th>项目</th><th>10分钟次数</th><th>性质</th></tr></thead><tbody><tr><td>🥇</td><td>AMD EeuDumps（双 GPU）</td><td>~15,800</td><td>驱动 Bug</td></tr><tr><td>🥇</td><td>微信 aconfig.dat</td><td>~6,200</td><td>正常但频率高</td></tr><tr><td>🥇</td><td>联想 devicecenter</td><td>~2,100</td><td>OEM 垃圾日志</td></tr><tr><td>🥇</td><td>Chrome 缓存</td><td>~1,500</td><td>浏览器正常</td></tr><tr><td>🥈</td><td>Windows Search</td><td>~200</td><td>索引</td></tr><tr><td>🥉</td><td>OpenCode / Codex</td><td>&lt;100</td><td>极少</td></tr></tbody></table><h3 id="process-explorer-抓到的写入字节排行" tabindex="-1">Process Explorer 抓到的写入字节排行 <a class="header-anchor" href="#process-explorer-抓到的写入字节排行" aria-label="Permalink to &quot;Process Explorer 抓到的写入字节排行&quot;">​</a></h3><table tabindex="0"><thead><tr><th>#</th><th>进程</th><th>写入量</th><th>性质</th></tr></thead><tbody><tr><td>🥇</td><td>OpenCode</td><td>~312 MB</td><td>prompt-history 持续追加</td></tr><tr><td>🥈</td><td>讯飞输入法</td><td>~56 MB</td><td>词库同步</td></tr><tr><td>🥉</td><td>Edge/Chrome</td><td>~60 MB</td><td>浏览器缓存</td></tr><tr><td>4</td><td>WeChat</td><td>~48 MB</td><td>正常使用</td></tr><tr><td>5</td><td>联想</td><td>~10 MB</td><td>已被阻断</td></tr></tbody></table><p><strong>对比发现</strong>：AMD 和微信是次数之王，OpenCode 是字节之王。DiskSleuth 和 Process Explorer 必须交叉使用才能看到全貌。</p><hr><h2 id="已执行的操作" tabindex="-1">已执行的操作 <a class="header-anchor" href="#已执行的操作" aria-label="Permalink to &quot;已执行的操作&quot;">​</a></h2><h3 id="✅-1-amd-eeudumps-日志风暴" tabindex="-1">✅ 1. AMD EeuDumps 日志风暴 <a class="header-anchor" href="#✅-1-amd-eeudumps-日志风暴" aria-label="Permalink to &quot;✅ 1. AMD EeuDumps 日志风暴&quot;">​</a></h3><ul><li><strong>问题</strong>：AMD External Events Utility 在每次移动/调整窗口时写入 GPU 诊断日志</li><li><strong>原因</strong>：AMD 驱动 Bug，自 2025 年 11 月被 Reddit 用户 Takia_Gecko 发现，Tom&#39;s Hardware 等多家媒体报道</li><li><strong>涉及文件</strong>： <ul><li><code>C:\\Windows\\System32\\DriverStore\\FileRepository\\amdfendr.inf_amd64_*\\AMD\\EeuDumps\\R-gpu-*.log</code></li><li><code>C:\\Windows\\System32\\AMD\\EEUDumps\\R-gpu-*.log</code></li></ul></li><li><strong>存档大小</strong>：DriverStore 路径下 207 个文件共 114 MB</li><li><strong>解决方案</strong>：<div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes vitesse-light vitesse-dark vp-code" style="--shiki-light:#393a34;--shiki-dark:#dbd7caee;--shiki-light-bg:#ffffff;--shiki-dark-bg:#121212;" tabindex="0"><code><span class="line"><span>sc.exe stop &quot;AMD External Events Utility&quot;</span></span>
<span class="line"><span>sc.exe config &quot;AMD External Events Utility&quot; start=disabled</span></span></code></pre></div></li><li><strong>效果</strong>：写入归零。FreeSync 等显卡功能不受影响。</li><li><strong>参考</strong>：<a href="https://www.tomshardware.com/software/windows/amd-users-flag-heavy-ssd-write-activity-tied-to-chipset-driver-incessant-log-file-writes-observed-every-time-a-window-is-moved-or-resized" target="_blank" rel="noreferrer">https://www.tomshardware.com/software/windows/amd-users-flag-heavy-ssd-write-activity-tied-to-chipset-driver-incessant-log-file-writes-observed-every-time-a-window-is-moved-or-resized</a></li></ul><h3 id="✅-2-联想-devicecenter-日志" tabindex="-1">✅ 2. 联想 devicecenter 日志 <a class="header-anchor" href="#✅-2-联想-devicecenter-日志" aria-label="Permalink to &quot;✅ 2. 联想 devicecenter 日志&quot;">​</a></h3><ul><li><strong>问题</strong>：Lenovo Vantage / Lenovo PCManager 预装软件疯狂写日志</li><li><strong>涉及文件</strong>：<code>C:\\ProgramData\\Lenovo\\devicecenter\\logs\\</code> 下 66 个日志文件</li><li><strong>解决方案</strong>：<div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes vitesse-light vitesse-dark vp-code" style="--shiki-light:#393a34;--shiki-dark:#dbd7caee;--shiki-light-bg:#ffffff;--shiki-dark-bg:#121212;" tabindex="0"><code><span class="line"><span>Remove-Item &quot;C:\\ProgramData\\Lenovo\\devicecenter\\logs\\*&quot; -Force</span></span>
<span class="line"><span>icacls &quot;C:\\ProgramData\\Lenovo\\devicecenter\\logs&quot; /deny &quot;Everyone:(W)&quot;</span></span>
<span class="line"><span>icacls &quot;$env:LOCALAPPDATA\\Lenovo&quot; /deny &quot;Everyone:(W)&quot;</span></span>
<span class="line"><span>icacls &quot;$env:APPDATA\\Lenovo&quot; /deny &quot;Everyone:(W)&quot;</span></span></code></pre></div></li><li><strong>注意</strong>：保留 <code>LenovoFnAndFunctionKeys</code>、<code>LenovoHotkeyService</code> 服务</li><li><strong>效果</strong>：写入大幅减少（从 700+ 降到 ~10 次）</li></ul><h3 id="✅-3-office-clicktorun-残留" tabindex="-1">✅ 3. Office ClickToRun 残留 <a class="header-anchor" href="#✅-3-office-clicktorun-残留" aria-label="Permalink to &quot;✅ 3. Office ClickToRun 残留&quot;">​</a></h3><ul><li><strong>问题</strong>：Office 卸载后残留 ClickToRun 安装器 146 MB</li><li><strong>已清理</strong>：<code>C:\\Program Files\\Common Files\\microsoft shared\\ClickToRun</code></li></ul><hr><h2 id="待处理的" tabindex="-1">待处理的 <a class="header-anchor" href="#待处理的" aria-label="Permalink to &quot;待处理的&quot;">​</a></h2><table tabindex="0"><thead><tr><th>项目</th><th>状态</th><th>计划</th></tr></thead><tbody><tr><td>OpenCode prompt-history</td><td>待处理</td><td>关掉历史记录或限制写入频率</td></tr><tr><td>Windows Search</td><td>待处理</td><td>不用 Win+S 就关掉</td></tr><tr><td>微信 WeChat Files 迁移</td><td>不处理</td><td>数据重要，写入量不大可以接受</td></tr><tr><td>傲腾外接盘管理</td><td>待评估</td><td>把可丢弃的缓存重定向到外接傲腾</td></tr><tr><td>Chrome/Edge 缓存迁移</td><td>待评估</td><td>可以 mklink 到其他盘</td></tr><tr><td>Codex logs_2.sqlite 定时清理</td><td>待处理</td><td>每周 VACUUM</td></tr></tbody></table><hr><h2 id="结论" tabindex="-1">结论 <a class="header-anchor" href="#结论" aria-label="Permalink to &quot;结论&quot;">​</a></h2><ol><li><strong>AMD 驱动日志 Bug 是最大的写入元凶</strong>，好在已被社区发现并有成熟解决方案</li><li><strong>频次和字节是两个维度</strong>，DiskSleuth + Process Explorer 缺一不可</li><li><strong>微信虽然写入频次高但字节少</strong>，不值得为了节省写入量去动重要数据</li><li><strong>OpenCode（本工具）反而是按字节算最大的写入者</strong>，prompt-history.jsonl 持续累积</li><li><strong>SSD 的真实杀手是 WAF 而非写入次数</strong>，小文件随机写入的物理磨损比看起来大得多</li><li><strong>Windows 定位磁盘写入的工具没有完美的</strong>，需要交叉验证</li></ol>`,42)])])}const g=e(i,[["render",s]]);export{p as __pageData,g as default};
